const rosterDb=()=>new Promise<IDBDatabase>((resolve,reject)=>{const req=indexedDB.open("rumbo-rosters",1);req.onupgradeneeded=()=>req.result.createObjectStore("pdfs",{keyPath:"id"});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});
const saveRosterPdf=async(meta:SavedRoster,blob:Blob,items?:Duty[])=>{const db=await rosterDb();await new Promise<void>((resolve,reject)=>{const tx=db.transaction("pdfs","readwrite");tx.objectStore("pdfs").put({...meta,blob,items});tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});db.close()};
const listRosterPdfs=async()=>{const db=await rosterDb();const data=await new Promise<any[]>((resolve,reject)=>{const r=db.transaction("pdfs").objectStore("pdfs").getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});db.close();return data.sort((a,b)=>b.importedAt.localeCompare(a.importedAt)) as RosterRecord[]};
const deleteRosterPdf=async(id:string)=>{const db=await rosterDb();await new Promise<void>((resolve,reject)=>{const tx=db.transaction("pdfs","readwrite");tx.objectStore("pdfs").delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});db.close()};

function RosterLibrary({items,onImport,onDelete}:{items:RosterRecord[],onImport:()=>void,onDelete:(r:SavedRoster)=>void}){return <section className="roster-library"><div className="roster-title"><div><p className="eyebrow">ARCHIVO PERSONAL</p><h1>Mis rosters</h1><p>Los PDF quedan guardados solamente en este dispositivo.</p></div><button className="import" onClick={onImport}>⇧ Importar PDF</button></div>{items.length?<div className="roster-list">{items.map(r=><div className="roster-item" key={r.id}><button onClick={()=>{const url=URL.createObjectURL(r.blob);window.open(url,"_blank","noopener,noreferrer");setTimeout(()=>URL.revokeObjectURL(url),60000)}}><span className="pdf-icon">PDF</span><div><b>{r.name}</b><small>{new Date(r.from+"T12:00").toLocaleDateString("es-AR",{day:"numeric",month:"short",year:"numeric"})} - {new Date(r.to+"T12:00").toLocaleDateString("es-AR",{day:"numeric",month:"short",year:"numeric"})}</small><small>Importado {new Date(r.importedAt).toLocaleString("es-AR")} · {r.count} jornadas</small></div><span className="open-pdf">Abrir PDF ›</span></button><button className="delete-roster" onClick={()=>onDelete(r)}>Eliminar</button></div>)}</div>:<div className="empty-rosters"><span>▤</span><h2>Todavía no guardaste ningún roster</h2><p>Importá un PDF para conservarlo, verlo y usarlo en el calendario.</p><button onClick={onImport}>Elegir PDF</button></div>}</section>}

const minutes=(value?:string)=>{if(!value||!/^[0-2]?\d:[0-5]\d$/.test(value))return 0;const [h,m]=value.split(":").map(Number);return h*60+m};
