const toTenths=(totalMinutes:number)=>{const hours=Math.floor(totalMinutes/60),rest=totalMinutes%60;const tenth=rest<=2?0:rest<=8?1:rest<=14?2:rest<=20?3:rest<=26?4:rest<=33?5:rest<=39?6:rest<=45?7:rest<=51?8:rest<=57?9:10;return hours*10+tenth};
