  useEffect(()=>{try{const stored=localStorage.getItem("crew-roster-logbook-settings"),drafts=localStorage.getItem("crew-roster-logbook-rows");if(stored){const legacy=JSON.parse(stored),oldCategory=["Reactor","Turbohélice","Pistón"].includes(legacy.power)?legacy.power:null;setSettings({...defaultLogbook,...legacy,power:oldCategory?defaultLogbook.power:legacy.power??defaultLogbook.power,propulsion:legacy.propulsion??oldCategory??defaultLogbook.propulsion,initialInstrumentCopilot:legacy.initialInstrumentCopilot??legacy.initialInstrument??0});setTotalsOpen(false)}if(drafts)setRows(JSON.parse(drafts))}catch{}},[]);
  useEffect(()=>setRows(current=>sourceRows.map(row=>{const previous=current.find(item=>item.id===row.id);if(previous)return{...row,...previous,purpose:previous.purpose||settings.purpose,area:previous.area||"Travesía"};const instrument=settings.instrumentRule==="minus10"?Math.max(0,row.minutes-10):settings.instrumentRule==="manual"?0:row.minutes;return{...row,registration:settings.registration,instrumentMinutes:instrument}})),[sourceRows,settings.instrumentRule,settings.registration,settings.purpose]);
  const updateSettings=<K extends keyof LogbookSettings>(field:K,value:LogbookSettings[K])=>{setSaved(false);setSettings(current=>({...current,[field]:value,...(field==="initialInstrumentCopilot"?{initialInstrument:value}:{}),...(field==="initialCrossCountryDayCopilot"?{initialCopilot:value}:{})}))};
